[InitializeOnLoad]public static class Casino3DUpgrade{const string D="Assets/Scenes/Oasis/Casino3DSigns";static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static Casino3DUpgrade(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("Casino3DUpgrade.request"))return;File.Delete("Casino3DUpgrade.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/Casino3DUpgrade.txt",e.ToString());Debug.LogException(e);}}static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(scene.GetRootGameObjects().Any(g=>g.name=="Casino Crown 3D Logo and Facade Lighting"))throw new Exception("Casino feature already exists");var casino=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(f=>f.name=="Casino");var original=casino.sharedMesh;var originalMat=casino.GetComponent<Renderer>().sharedMaterial;var matrix=casino.transform.localToWorldMatrix;Directory.CreateDirectory(D);Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeCasino3DUpgrade");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeCasino3DUpgrade/Scene.unity",true);var data=typeof(FinalPNGCityDetails).GetMethod("Read",F).Invoke(null,new object[]{original});var local=(Vector3[])data.GetType().GetField("p").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);var p=local.Select(casino.transform.TransformPoint).ToArray();Func<float,float,float> front=(y,z)=>{float x=-999;for(int i=0;i<ids.Length;i+=3){var a=p[ids[i]];var b=p[ids[i+1]];var c=p[ids[i+2]];float det=(b.z-c.z)*(a.y-c.y)+(c.y-b.y)*(a.z-c.z);if(Mathf.Abs(det)<.00001f)continue;float u=((b.z-c.z)*(y-c.y)+(c.y-b.y)*(z-c.z))/det,v=((c.z-a.z)*(y-c.y)+(a.y-c.y)*(z-c.z))/det;if(u>=-.0001f&&v>=-.0001f&&u+v<=1.0001f)x=Mathf.Max(x,u*a.x+v*b.x+(1-u-v)*c.x);}return x;};var gold=new List<Vector3[]>();var red=new List<Vector3[]>();foreach(float z in new[]{-524f,-510f,-