}),new LOD(.004f,new[]{fr})});lod.RecalculateBounds();var accent=add(master,"Warm gold and red original facade edge lights",trim);var tg=accent.gameObject.AddComponent<LODGroup>();tg.SetLODs(new[]{new LOD(.003f,new[]{accent})});tg.RecalculateBounds();PrefabUtility.SaveAsPrefabAssetAndConnect(master,D+"/Casino Crown 3D Logo and Facade Lighting.prefab",InteractionMode.AutomatedAction);if(casino.sharedMesh!=original||casino.GetComponent<Renderer>().sharedMaterial!=originalMat||casino.transform.localToWorldMatrix!=matrix)throw new Exception("Native building unexpectedly changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",F);var camera=new Vector3(-325,45,-494.23f);var target=new Vector3(-390,44,-494.23f);capture.Invoke(null,new object[]{scene,camera,target,"Casino-3D-Logo-Day"});var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();if(ctrl){bool night=ctrl.IsNight;try{ctrl.ApplyNight();capture.Invoke(null,new object[]{scene,camera,target,"Casino-3D-Logo-Night"});}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();}}File.WriteAllText("FinalEnvironmentRoadReview/Casino3DUpgrade.txt","SUCCESS: raised CASINO gold lettering, crown, five playing cards, two red dice, illuminated oval and native facade gold/red edge accents. Original building mesh/material/transform untouched and verified. No new texture/material/realtime lights. Near triangles="+near.triangles.Length/3+" far="+far.triangles.Length/3+" accent="+trim.triangles.Length/3+" shader errors="+ShaderUtil.ShaderHasError(mat.shader));}}
